-- Undo for photo batch 2026-11-01. Removes exactly the URLs under https://www.gowayfind.com/place-photos/batch-2026-11/
-- from the four photo arrays, then restores the arrays of the places the dedupe section edited from before_snapshot.json.
begin;
create or replace function pg_temp.strip(s jsonb) returns jsonb language sql immutable as $$
  select s
   || case when s ? 'photos' then jsonb_build_object('photos', coalesce((select jsonb_agg(e order by o) from jsonb_array_elements(s->'photos') with ordinality t(e,o) where (e #>> '{}') not like 'https://www.gowayfind.com/place-photos/batch-2026-11/%'),'[]')) else '{}'::jsonb end
   || case when s ? 'photo_gallery' then jsonb_build_object('photo_gallery', coalesce((select jsonb_agg(e order by o) from jsonb_array_elements(s->'photo_gallery') with ordinality t(e,o) where coalesce(e->>'url','') not like 'https://www.gowayfind.com/place-photos/batch-2026-11/%'),'[]')) else '{}'::jsonb end
   || case when s ? 'haunt_photo_gallery' then jsonb_build_object('haunt_photo_gallery', coalesce((select jsonb_agg(e order by o) from jsonb_array_elements(s->'haunt_photo_gallery') with ordinality t(e,o) where coalesce(e->>'url','') not like 'https://www.gowayfind.com/place-photos/batch-2026-11/%'),'[]')) else '{}'::jsonb end
   || case when s ? 'christmas_photo_gallery' then jsonb_build_object('christmas_photo_gallery', coalesce((select jsonb_agg(e order by o) from jsonb_array_elements(s->'christmas_photo_gallery') with ordinality t(e,o) where coalesce(e->>'url','') not like 'https://www.gowayfind.com/place-photos/batch-2026-11/%'),'[]')) else '{}'::jsonb end
$$;
update wf_inventory set signals = pg_temp.strip(signals) where signals::text like '%https://www.gowayfind.com/place-photos/batch-2026-11/%';
